import type { EntityInput, InstitutionInput, PersonInput, TrialInput } from "@/lib/schema";
import type { UkPathway, UkSource } from "@/lib/uk-pathway";
import type { Spike } from "./index";

/**
 * SKIN CANCER: THE UK AND NHS LAYER, KEYED TO THE FAMILY. Facts checked 2026-09-25 against the pages cited on
 * each row.
 *
 * Skin cancer is the pathway where the NHS behaves least like it does for any other cancer, and that is the
 * reason this page exists. Three facts govern everything below and each one is sourced here rather than
 * asserted: skin is the largest single stream of urgent cancer referrals in England, 89,978 of the 308,200
 * urgent suspected cancer referrals made in July 2026, 29.2 percent of the total and nearly twice the number
 * for breast; basal cell carcinoma, which is the commonest cancer in human beings, is written out of the
 * treatment waiting-time standards by name, so the 5,733 skin treatments counted against the 62-day standard in
 * the same month are not the same disease as the 89,978 referrals; and the Office for National Statistics
 * excludes the whole of ICD-10 C44 from "all cancers" because it is, in its own words, greatly under-registered.
 * Every incidence figure a reader will meet for this disease rests on those two exclusions.
 *
 * What is here and nowhere else in the corpus: the referral rules with their recommendation numbers, including
 * the one that says a basal cell carcinoma should get a routine referral and not an urgent one; the cancer
 * waiting times monitoring guidance read in full, with the exact list of what is in scope and what is out and
 * the teledermatology clock-stop rules; the timed diagnostic pathway with the finding that around 93 percent of
 * people referred urgently do not have cancer; teledermatology and the conditional recommendation of an
 * artificial intelligence triage device; who may cut out which lesion and where, read from the criteria box in
 * the cancer service guideline rather than described; Mohs surgery provision with the number of surgeons and
 * centres from the national dermatology audit; the funding table for the keratinocyte cancers, which no other
 * page carries, including the refusal, the licensed medicine that was never appraised at all and the medicine
 * the NHS funds through a commissioning route rather than an appraisal; prevention, which for this cancer is the
 * largest lever there is, with the legislation nation by nation and what is not in it; and the four nations,
 * which do not even agree on which of these diseases counts as a cancer for waiting-time purposes.
 *
 * The pathway is keyed to the family id `skin-cancer` because the referral, the clinic, the standards, the
 * multidisciplinary team and the four-nation differences are the same whichever histology comes back. The
 * keratinocyte cancers and melanoma are aliases. What is specific to melanoma stays on the melanoma records:
 * this page routes to them and does not restate them. Uveal and conjunctival melanoma are deliberately not
 * aliases, because they are eye cancers on an ocular oncology pathway, not a dermatology one.
 *
 * No figure is remembered: each carries the page it was read from. Where a page could not be read, the gap is
 * named with the response the server gave.
 */
const asOf = "2026-09-25";

const nice = (code: string) => `https://www.nice.org.uk/guidance/${code}`;
const niceTerminated = (code: string) => `https://www.nice.org.uk/guidance/terminated/${code}`;
const smc = (slug: string) => `https://scottishmedicines.org.uk/medicines-advice/${slug}/`;
const isrctn = (n: string) => `https://www.isrctn.com/ISRCTN${n}`;
const CRUK = "https://www.cancerresearchuk.org/health-professional/cancer-statistics/statistics-by-cancer-type";

const S = {
  // ---------- How these cancers are counted ----------
  cwtGuide: { label: "NHS England: national cancer waiting times monitoring dataset guidance. Section 3.2: the treatment standards apply to ICD-10 C00 to C97 excluding basal cell carcinoma of skin, and to D05; section 5.10 puts C43 and C44 in scope but names seven excluded conditions (basal cell carcinoma, multicentric basal cell carcinoma, morphoeic basal cell carcinoma, fibroepithelial basal cell carcinoma, basosquamous carcinoma, metatypical carcinoma and pilomatrix carcinoma) and puts lentigo maligna, Bowen's disease, intraepidermal carcinoma and keratoacanthoma out of scope as well. The page answered HTTP 202 with an empty web application firewall challenge to OnCo on 25 September 2026; its full text was read through the site's own WordPress interface", url: "https://www.england.nhs.uk/long-read/national-cancer-waiting-times-monitoring-dataset-guidance/", date: "2025-04-09" },
  onsQmi: { label: "Office for National Statistics: cancer registration statistics quality and methodology information. \"We have been advised by expert epidemiologists and members of the former Steering Committee on Cancer Registration that non-melanoma skin cancer (NMSC) is greatly under-registered. Therefore, the published tables present counts and rates for all cancers and for all cancers excluding NMSC (code 173 in ICD-8 and ICD-9, and C44 in ICD-10) to ensure that the reported figures are meaningful\"", url: "https://www.ons.gov.uk/peoplepopulationandcommunity/healthandsocialcare/conditionsanddiseases/methodologies/cancerregistrationstatisticsqmi", date: "2026-09-25" },
  skinPathway: { label: "NHS England: implementing a timed skin cancer diagnostic pathway, publication approval reference PAR1350, 21 October 2022. Around 215,000 skin cancers a year in England; over 155,000 new basal cell carcinomas in 2018 (around 72 percent of skin cancers), around 45,000 cutaneous squamous cell carcinomas (21 percent) and around 15,000 melanomas (7 percent); around 93 percent of people referred urgently with a suspicious skin lesion do not have cancer, with cancer alliance variation from 81 to 98 percent; the slowest 5 percent of referrals take 27 days or longer to be seen; about a third of people with squamous cell carcinoma or melanoma are not referred on an urgent cancer pathway; annex 1 puts basal cell carcinoma out of scope", url: "https://www.england.nhs.uk/wp-content/uploads/2018/04/B1350_Skin-cancer-timed-diagnostic-pathway.pdf", date: "2022-10-21" },
  cwtCsv: { label: "NHS England: cancer waiting times monthly combined data, April to July 2026, provisional. July 2026, England provider totals: 89,978 of 308,200 urgent suspected cancer referrals were for suspected skin cancer; 68,719 of 78,719 suspected skin cancer pathways met the 28-day Faster Diagnosis Standard (87.3 percent); 7,936 of 8,994 skin treatments met the 31-day standard (88.2 percent); 5,010 of 5,733 met the 62-day standard (87.4 percent), split 3,814 of 4,421 on the urgent suspected cancer route (86.3 percent) and 1,196 of 1,312 on the consultant upgrade route (91.2 percent). Across April to July 2026, 304,485 of 1,124,238 urgent suspected cancer referrals were for suspected skin cancer, 27.1 percent", url: "https://www.england.nhs.uk/statistics/wp-content/uploads/sites/2/2026/09/2026-27-Apr-Jul-Monthly-Combined-CSV-Provisional.csv", date: "2026-09-10" },
  cwtDefinitions: { label: "GOV.UK: waiting times for suspected and diagnosed cancer patients, July 2026 (the definitions of the 28, 31 and 62 day standards; published 10 September 2026)", url: "https://www.gov.uk/government/statistics/waiting-times-for-suspected-and-diagnosed-cancer-patients-for-july-2026", date: "2026-09-10" },
  cwtChanges: { label: "NHS England: changes to cancer waiting times standards from 1 October 2023. The two-week wait standard was removed in favour of the 28-day Faster Diagnosis Standard and the ten standards were rationalised to three; the letter says performance against breast and skin specifically would need to be above 90 percent for the Faster Diagnosis Standard to rise to 80 percent. The page answered HTTP 202 with an empty web application firewall challenge to OnCo on 25 September 2026", url: "https://www.england.nhs.uk/long-read/changes-to-cancer-waiting-times-standards-from-1-october-2023/", date: "2023-08-17" },

  // ---------- Referral and the diagnostic route ----------
  ng12: { label: "NICE NG12: suspected cancer, recognition and referral, section 1.7 skin cancers. 1.7.1 refer on a suspected cancer pathway for melanoma with a weighted 7-point checklist score of 3 or more; 1.7.2 refer if dermoscopy suggests melanoma; 1.7.3 consider referral for nodular melanoma; 1.7.4 consider a suspected cancer pathway referral for a lesion that raises the suspicion of squamous cell carcinoma; 1.7.5 consider a non-urgent referral for a lesion that raises the suspicion of a basal cell carcinoma; 1.7.6 only consider an urgent referral for a suspected basal cell carcinoma if delay would have a significant impact because of site or size; 1.7.7 follow CSG8 on who should excise suspected basal cell carcinomas. Guideline published 23 June 2015, last updated 15 April 2026", url: `${nice("ng12")}/chapter/Recommendations-organised-by-site-of-cancer`, date: "2026-04-15" },
  csg8: { label: "NICE CSG8: improving outcomes for people with skin tumours including melanoma. Published 22 February 2006, last updated 25 May 2010, last reviewed 23 May 2019; NICE decided in December 2020 to retain but not update it. It recommends two levels of multidisciplinary team, that people with precancerous lesions be treated by their GP or referred, and that people needing specialist diagnosis be referred to a doctor trained to diagnose skin cancer", url: nice("csg8"), date: "2010-05-25" },
  csg8Pdf: { label: "NICE CSG8, the management of low-risk basal cell carcinomas in the community, cancer service guidance update, May 2010. Box 1 sets the criteria for the low-risk nodular basal cell carcinomas a GP with no special interest may excise under a directed or local enhanced service: the person must not be 24 or younger, immunosuppressed or have Gorlin's syndrome, and the lesion must be below the clavicle, under 1 cm with clearly defined margins, not recurrent or persistent after incomplete excision, not morphoeic, infiltrative or basosquamous, and not over important anatomical structures, in an area where primary closure is difficult, where difficult excision may give a poor cosmetic result, or at another highly visible site. Anything else, or any diagnostic doubt, goes to a member of the local skin cancer multidisciplinary team, and every incompletely excised basal cell carcinoma must be discussed with one", url: `${nice("csg8")}/resources/improving-outcomes-for-people-with-skin-tumours-including-melanoma-2010-partial-update-pdf-773380189`, date: "2010-05-25" },
  qs130: { label: "NICE QS130: skin cancer quality standard, published 21 September 2016, last updated 24 January 2024. Six statements: 1 integrated care boards work with local partners on strategies to raise awareness of skin cancer and the risks of over-exposure to sunlight and artificial ultraviolet light, particularly for at-risk groups (new 2024); 2 people with suspected melanoma, squamous cell carcinoma or a rare skin cancer are referred on a suspected cancer pathway to have a diagnosis confirmed or ruled out within 28 days; 3 dermoscopy at specialist assessment for suspected melanoma; 4 access to a skin cancer clinical nurse specialist for melanoma, high-risk squamous cell carcinoma or a rare skin cancer; 5 BRAF analysis in stage 2B to 4 primary melanoma; 6 a staging scan in stage 2C to 4 melanoma (new 2024)", url: `${nice("qs130")}/chapter/Quality-statements`, date: "2024-01-24" },
  ng14: { label: "NICE NG14: melanoma, assessment and management. Published 29 July 2015, last updated 27 July 2022", url: `${nice("ng14")}/chapter/Recommendations`, date: "2022-07-27" },
  niceSkinProducts: { label: "NICE: all products on skin cancer. Sixty-five products, of which two are prevention guidance (PH32 and NG34), one is a cancer service guideline (CSG8), one a quality standard (QS130), and the rest technology appraisals, HealthTech guidance and medtech innovation briefings", url: "https://www.nice.org.uk/guidance/conditions-and-diseases/cancer/skin-cancer/products", date: "2026-09-25" },

  // ---------- Teledermatology and artificial intelligence ----------
  teledermRoadmap: { label: "NHS England: a teledermatology roadmap, implementing safe and effective teledermatology triage pathways and processes. About 3 million dermatology outpatient appointments in England in the year to April 2022; dermatology receives more urgent referrals for suspected cancer than any other specialty; about half of the 1 million dermatology referrals a year are urgent suspected skin cancer referrals, of which about 8 percent turn out to be melanoma or squamous cell carcinoma; macroscopic images alone can diagnose many benign lesions and send some squamous cell carcinomas and many basal cell carcinomas straight to surgery, but both dermoscopic and macroscopic images are needed for pigmented lesions; rashes and lesions may be harder to assess in people with brown and black skin. The page answered HTTP 202 with an empty web application firewall challenge to OnCo on 25 September 2026", url: "https://www.england.nhs.uk/long-read/a-teledermatology-roadmap-implementing-safe-and-effective-teledermatology-triage-pathways-and-processes/", date: "2023-10-26" },
  htg746: { label: "NICE HTG746: artificial intelligence technologies for assessing and triaging skin lesions referred to the urgent suspected skin cancer pathway, early value assessment. Published 1 May 2025 as HTE24, migrated to HealthTech guidance and last updated 17 March 2026. Recommendation 1.1 allows Deep Ensemble for Recognition of Malignancy (DERM) within teledermatology services during a three-year evidence generation period, only while the evidence in the evidence generation plan is being generated and once it has regulatory approval including NHS England's Digital Technology Assessment Criteria; 1.2 requires a healthcare professional review for people with black or brown skin and regular monitoring of performance", url: `${nice("htg746")}/chapter/1-Recommendations`, date: "2026-03-17" },
  nhseAi: { label: "NHS England: AI based skin lesion analysis technology, the national response to the early value assessment. In 2023/24 over 650,000 people were referred onto the urgent suspected skin cancer pathway and 120,000 did not have cancer diagnosed or ruled out within 28 days; DERM has the potential to discharge around 30 percent of cases from the pathway. NHS England asks that patients are given information and give informed consent before DERM is used, that a site starts with a second clinical read, that a second read always takes place for people with black or brown skin throughout the three-year evidence generation period, and that sites join the AI in Dermatology Getting It Right First Time community of practice. The page answered HTTP 202 with an empty web application firewall challenge to OnCo on 25 September 2026", url: "https://www.england.nhs.uk/elective-care/best-practice-solutions/ai-based-skin-lesion-analysis-technology/", date: "2025-12-11" },
  mib311: { label: "NICE MIB311: digital technologies for the detection of melanoma, medtech innovation briefing, published 1 November 2022", url: nice("mib311"), date: "2022-11-01" },

  // ---------- Who treats it ----------
  girftDerm: { label: "Getting It Right First Time: dermatology. One in four people in England and Wales (13.2 million) see their GP about a skin condition every year, with 3.5 million outpatient or day surgery attendances; around half of all cancers in England and Wales are skin cancer and this is increasing by 8 percent a year. The page also records the cancer waiting times change that made the two-week wait clock stop for a teledermatology referral the date a specialist reviews the image rather than the date the patient is told", url: "https://gettingitrightfirsttime.co.uk/medical_specialties/dermatology/", date: "2026-09-25" },
  girftReport: { label: "Getting It Right First Time: dermatology national specialty report, September 2021. 508 whole-time-equivalent trained NHS dermatologists in England with 159 whole-time-equivalent vacant posts and 143 filled by locums; at least ten trusts have no dermatologist at all and around a third have very severe shortages; NHS dermatology units carry out over 200,000 surgical excisions a year; around 75 percent of patient visits for NHS skin care take place in primary care; skin cancer incidence is rising by around 8 percent a year, doubling at least every 14 to 15 years. On Mohs: just 79 dermatology doctors carrying out Mohs surgery in England, activity concentrated in fewer than 30 specialist centres, patients in Salford over ten times more likely to get Mohs than those in the worst-served areas, and the Dermatology Clinical Reference Group designating 56 English trusts as specialist skin cancer centres (specialist skin cancer multidisciplinary teams, or level 5)", url: "https://gettingitrightfirsttime.co.uk/wp-content/uploads/2021/09/DermatologyReport-Sept21o.pdf", date: "2021-09" },
  htg333: { label: "NICE HTG333: electrochemotherapy for primary basal cell carcinoma and primary squamous cell carcinoma, published 26 February 2014 as interventional procedures guidance IPG478 and migrated to HealthTech guidance unchanged. Recommendation 1.1: current evidence on safety raises no major concerns and evidence on efficacy is limited in quantity and quality, so the procedure should only be used with special arrangements for clinical governance, consent and local audit, and with submission of data to a register", url: `${nice("htg333")}/chapter/1-Recommendations`, date: "2014-02-26" },
  htg99: { label: "NICE HTG99: photodynamic therapy for non-melanoma skin tumours including premalignant and primary non-metastatic skin lesions, published 22 February 2006 as interventional procedures guidance IPG155 and migrated to HealthTech guidance unchanged", url: nice("htg99"), date: "2006-02-22" },
  htg714: { label: "NICE HTG714: epidermal radiotherapy using rhenium-188 paste for non-melanoma skin cancer, published 2 April 2024. Recommendation 1.1 says more research is needed and 1.2 says the procedure should only be done as part of a formal research study approved by a research ethics committee", url: `${nice("htg714")}/chapter/1-Recommendations`, date: "2024-04-02" },
  htg388: { label: "NICE HTG388: VivaScope 1500 and 3000 imaging systems for detecting skin cancer lesions, published 11 November 2015", url: nice("htg388"), date: "2015-11-11" },

  // ---------- Access: NICE, the SMC and the Cancer Drugs Fund ----------
  ta802: { label: "NICE TA802: cemiplimab for treating advanced cutaneous squamous cell carcinoma, published 29 June 2022. Recommendation 1.1 recommends it for metastatic or locally advanced cutaneous squamous cell carcinoma in adults when curative surgery or curative radiotherapy is not suitable, only if it is stopped at 24 months or earlier on progression and the company provides it under the commercial arrangement. The guidance updates and replaces TA592, under which cemiplimab was available through the Cancer Drugs Fund", url: `${nice("ta802")}/chapter/1-Recommendations`, date: "2022-06-29" },
  ta489: { label: "NICE TA489: vismodegib for treating basal cell carcinoma, published 22 November 2017. Recommendation 1.1: vismodegib is not recommended within its marketing authorisation for treating symptomatic metastatic basal cell carcinoma, or locally advanced basal cell carcinoma that is inappropriate for surgery or radiotherapy, in adults. Recommendation 1.2 protects people already on treatment", url: `${nice("ta489")}/chapter/1-Recommendations`, date: "2017-11-22" },
  ta517: { label: "NICE TA517: avelumab for treating metastatic Merkel cell carcinoma, published 11 April 2018 and last updated 21 April 2021. Recommendation 1.1 recommends it after 1 or more lines of chemotherapy for metastatic disease, only with the commercial arrangement; 1.2 records that the recommendation has been updated and replaced by TA691 for untreated disease", url: `${nice("ta517")}/chapter/1-Recommendations`, date: "2021-04-21" },
  ta691: { label: "NICE TA691: avelumab for untreated metastatic Merkel cell carcinoma, published 21 April 2021. Recommendation 1.1 recommends it for adults who have not had chemotherapy for metastatic disease, only with the commercial arrangement", url: `${nice("ta691")}/chapter/1-Recommendation`, date: "2021-04-21" },
  ta950: { label: "NICE TA950: nivolumab with relatlimab for untreated unresectable or metastatic melanoma in people 12 years and over, published 7 February 2024. Recommendation 1.1 recommends it only if treatment is stopped after 2 years, or earlier on progression, and the company provides it under the commercial arrangement. There is no PD-L1 restriction in the recommendation", url: `${nice("ta950")}/chapter/1-Recommendations`, date: "2024-02-07" },
  ta684: { label: "NICE TA684: nivolumab for adjuvant treatment of completely resected melanoma with lymph node involvement or metastatic disease, published 17 March 2021. Recommendation 1.1 recommends it within its marketing authorisation with the commercial arrangement. It updated and replaced TA558 of 23 January 2019", url: `${nice("ta684")}/chapter/1-Recommendations`, date: "2021-03-17" },
  ta558: { label: "NICE TA558: nivolumab for adjuvant treatment of completely resected melanoma with lymph node involvement or metastatic disease, published 23 January 2019. The page states that the guidance has been updated and replaced by TA684", url: nice("ta558"), date: "2019-01-23" },
  ta766: { label: "NICE TA766: pembrolizumab for adjuvant treatment of completely resected stage 3 melanoma, published 2 February 2022. Recommendation 1.1 recommends it within its marketing authorisation for adjuvant treatment of completely resected stage 3 melanoma with lymph node involvement in adults, only with the commercial arrangement", url: `${nice("ta766")}/chapter/1-Recommendations`, date: "2022-02-02" },
  ta837: { label: "NICE TA837: pembrolizumab for adjuvant treatment of resected stage 2B or 2C melanoma, published 26 October 2022. Recommendation 1.1 recommends it within its marketing authorisation for completely resected stage 2B or 2C melanoma in people 12 years and over, only with the commercial arrangement", url: `${nice("ta837")}/chapter/1-Recommendations`, date: "2022-10-26" },
  ta980: { label: "NICE TA980: nivolumab for adjuvant treatment of completely resected melanoma at high risk of recurrence in people 12 years and over, terminated appraisal, 5 June 2024. The advice reads: NICE is unable to make a recommendation because Bristol-Myers Squibb did not provide an evidence submission, and NICE will review the decision if the company decides to make one", url: niceTerminated("ta980"), date: "2024-06-05" },
  ta400: { label: "NICE TA400: nivolumab in combination with ipilimumab for treating advanced melanoma, published 27 July 2016. Recommendation 1.1 recommends the combination within its marketing authorisation for advanced unresectable or metastatic melanoma in adults, only when the company provides ipilimumab with the patient access scheme discount", url: `${nice("ta400")}/chapter/1-Recommendations`, date: "2016-07-27" },
  ta366: { label: "NICE TA366: pembrolizumab for advanced melanoma not previously treated with ipilimumab, published 25 November 2015, last updated 12 September 2017", url: nice("ta366"), date: "2017-09-12" },
  ta396: { label: "NICE TA396: trametinib in combination with dabrafenib for treating unresectable or metastatic melanoma, published 22 June 2016", url: nice("ta396"), date: "2016-06-22" },
  ta562: { label: "NICE TA562: encorafenib with binimetinib for unresectable or metastatic BRAF V600 mutation-positive melanoma, published 27 February 2019", url: nice("ta562"), date: "2019-02-27" },
  ta410: { label: "NICE TA410: talimogene laherparepvec for treating unresectable metastatic melanoma, published 28 September 2016", url: nice("ta410"), date: "2016-09-28" },
  niceIdCscc: { label: "NICE: cemiplimab for adjuvant treatment of high-risk cutaneous squamous cell carcinoma after surgery and radiotherapy [ID6659], in development, expected publication 24 March 2027; cosibelimab for treating advanced cutaneous squamous cell carcinoma [ID6663], awaiting development, expected 23 September 2027; pembrolizumab for adjuvant treatment of locally advanced cutaneous squamous cell carcinoma after surgery and radiotherapy [ID6473], in development, publication date to be confirmed", url: "https://www.nice.org.uk/guidance/conditions-and-diseases/cancer/skin-cancer/products", date: "2026-09-25" },
  cdfList: { label: "NHS England: national Cancer Drugs Fund list version 1.408, 24 September 2026, 320 pages. Section A is what the Cancer Drugs Fund pays for; section B is what NHS England funds routinely. Blueteq form VIS2 sits in section B: vismodegib is routinely funded from 14 July 2021, with no technology appraisal number, for adults with at least six clinically evident non-locally advanced, non-metastatic basal cell carcinomas of which at least three are 5 mm or larger, with or without Gorlin syndrome, where the person is suitable for surgery but surgery alone has the potential for substantial disfigurement, on the recommendation of a specialised skin cancer or head and neck multidisciplinary team. The form records that vismodegib and the intermittent schedules are not licensed in this indication. Forms CEM1 (TA802) and AVE1 and AVE2 (TA691 and TA517) are also in section B, so cemiplimab for advanced cutaneous squamous cell carcinoma and avelumab for Merkel cell carcinoma are routine commissioning and not managed access", url: "https://www.england.nhs.uk/wp-content/uploads/2017/04/national-cancer-drugs-fund-list-v1.408.pdf", date: "2026-09-24" },
  smcSkin: { label: "Scottish Medicines Consortium: medicines advice (the keywords parameter, which the search form does not offer, returns the advices with their SMC numbers in the slug)", url: "https://scottishmedicines.org.uk/medicines-advice/?keywords=skin", date: "2026-09-25" },
  smcCemiplimab: { label: "Scottish Medicines Consortium SMC2584: cemiplimab (Libtayo) accepted for use within NHSScotland following reassessment under the end of life and orphan equivalent medicine process, for metastatic or locally advanced cutaneous squamous cell carcinoma in adults who are not candidates for curative surgery or curative radiation; objective response rate 45 percent in the phase 2 study; takes account of a Patient and Clinician Engagement meeting; supersedes the earlier interim acceptance SMC2216", url: smc("cemiplimab-libtayo-reassessment-smc2584"), date: "2026-09-25" },
  smcAvelumab: { label: "Scottish Medicines Consortium 1315/18: avelumab (Bavencio) accepted for use within NHSScotland following a full submission considered under the ultra-orphan and end of life process, for metastatic Merkel cell carcinoma in adults; takes account of a Patient and Clinician Engagement meeting", url: smc("avelumab-bavencio-fullsubmission-131518"), date: "2026-09-25" },
  smcVismodegib: { label: "Scottish Medicines Consortium 924/13: vismodegib (Erivedge) is not recommended for use within NHS Scotland in the absence of a submission from the holder of the marketing authorisation, for symptomatic metastatic basal cell carcinoma and locally advanced basal cell carcinoma inappropriate for surgery or radiotherapy", url: smc("vismodegib-erivedge-nonsubmission-92413"), date: "2026-09-25" },
  smcImiquimod: { label: "Scottish Medicines Consortium 167/05: imiquimod 5% cream (Aldara) accepted for restricted use within NHS Scotland for the topical treatment of small superficial basal cell carcinoma in adults in whom standard treatment with surgery or cryotherapy is contraindicated, supervised by specialists in dermatology; composite clearance 73 to 77 percent at 12 weeks in the randomised trials", url: smc("imiquimod-5-cream-aldara-fullsubmission-16705"), date: "2026-09-25" },
  smcMetvix: { label: "Scottish Medicines Consortium 51/03: methyl aminolevulinate cream (Metvix) accepted for restricted use within NHS Scotland for basal cell carcinoma in people in whom standard treatment with surgery or cryotherapy is contraindicated, restricted to specialist dermatologists and to superficial lesions", url: smc("methyl-aminolevulinate-metvix-cream-resubmission-5103"), date: "2026-09-25" },
  smcPembroAdj: { label: "Scottish Medicines Consortium SMC2526: pembrolizumab (Keytruda) accepted for use within NHSScotland for adjuvant treatment of adults and adolescents 12 and over with completely resected stage 2B or 2C melanoma; it had previously been accepted for resected stage 3 melanoma with lymph node involvement under SMC2144", url: smc("pembrolizumab-keytruda-full-smc2526"), date: "2026-09-25" },
  smcNivoNonSub: { label: "Scottish Medicines Consortium SMC2704: nivolumab (Opdivo) is not recommended for use within NHSScotland for adjuvant treatment of stage 2B or 2C melanoma in the absence of a submission from the holder of the marketing authorisation", url: smc("nivolumab-opdivo-nonsub-smc2704"), date: "2026-09-25" },
  smcOpdualag: { label: "Scottish Medicines Consortium SMC2645: nivolumab with relatlimab (Opdualag) accepted for use within NHSScotland for first-line treatment of advanced unresectable or metastatic melanoma in adults and adolescents 12 and over", url: smc("nivolumab-relatlimab-opdualag-full-smc2645"), date: "2026-09-25" },
  smcEncorafenib: { label: "Scottish Medicines Consortium SMC2238: encorafenib (Braftovi) accepted for use within NHSScotland with binimetinib for unresectable or metastatic BRAF V600 mutation-positive melanoma, following a resubmission assessed under the end of life and orphan medicine process and a Patient and Clinician Engagement meeting", url: smc("encorafenib-braftovi-resubmission-smc2238"), date: "2026-09-25" },
  smcTvec: { label: "Scottish Medicines Consortium 1248/17: talimogene laherparepvec (Imlygic) considered in the absence of a submission from the holder of the marketing authorisation", url: smc("talimogene-laherparepvec-imlygic-nonsubmission-124817"), date: "2026-09-25" },
  awmsgNice: { label: "All Wales Therapeutics and Toxicology Centre: AWMSG in relation to NICE. The AWMSG does not appraise a medicine that NICE is appraising; NICE guidance applies in Wales", url: "https://awttc.nhs.wales/accessing-medicines/pharmaceutical-industry-submissions/submit-for-awmsg-appraisal/invisible/awmsg-in-relation-to-nice1/", date: "2026-09-25" },
  ntf: { label: "Welsh Government: the New Treatment Fund, which makes medicines recommended by NICE and the AWMSG available within 60 days", url: "https://www.gov.wales/new-treatment-fund-improving-and-prolonging-lives-across-wales-0", date: "2026-09-25" },

  // ---------- Tests ----------
  ngtdCancer: { label: "NHS England: cancer (non-central nervous system) national genomic test directory, version 16. Clinical indication M7 melanoma in adults: M7.1 multi-target next-generation sequencing small variant panel covering BRAF, KIT and NRAS, for primary melanomas at high risk of recurrence (stage 2C, 3 or 4); M7.2 BRAF hotspot testing where a panel cannot be delivered; M7.5 to M7.9 fluorescence in situ hybridisation for MYB, RREB1, CCND1, MYC and CDKN2A, and M7.10 genome-wide copy number by microarray, where molecular assessment will aid the diagnosis or management of an equivocal melanocytic lesion. M187 uveal melanoma and M241 conjunctival melanoma have their own indications. There is no clinical indication for basal cell carcinoma, cutaneous squamous cell carcinoma or Merkel cell carcinoma anywhere in the directory; dermatofibrosarcoma protuberans is M50.1 on the sarcoma sheet", url: "https://www.england.nhs.uk/wp-content/uploads/2018/08/cancer-non-central-nervous-system-national-genomic-test-directory-version-16.xlsx", date: "2026-09-25" },
  ngtdRid: { label: "NHS England: rare and inherited disease national genomic test directory, version 9. R214.1 nevoid basal cell carcinoma syndrome or Gorlin syndrome, small panel covering PTCH1 and SUFU, specialised inherited cancer service; R254.1 familial melanoma, small panel, specialised inherited cancer service; R227.1 and R227.2 xeroderma pigmentosum, trichothiodystrophy or Cockayne syndrome, a small panel and genome-wide DNA repair defect testing, highly specialised dermatology service", url: "https://www.england.nhs.uk/wp-content/uploads/2018/08/rare-and-inherited-disease-national-genomics-test-directory-v9.xlsx", date: "2026-09-25" },
  genomicService: { label: "NHS England: the NHS Genomic Medicine Service, through which seven Genomic Laboratory Hubs deliver the test directory in England (the page answered HTTP 202 with an empty web application firewall challenge to OnCo on 25 September 2026)", url: "https://www.england.nhs.uk/genomics/nhs-genomic-med-service/", date: "2026-09-25" },

  // ---------- Prevention ----------
  ph32: { label: "NICE PH32: skin cancer prevention, published 26 January 2011, last updated 9 February 2016. Recommendations 1 to 5 were replaced by NG34 in February 2016, leaving recommendation 6 on providing shade when designing and constructing new buildings and when developing communal outdoor areas. The guidance records that no recommendation was made on multi-component interventions or on adding shade structures to existing buildings because they were not cost effective, that no recommendation was made on protective clothing or sunscreen alone because no studies were identified, and that policy, fiscal and legislative actions such as banning unsupervised or coin-operated sunbed facilities, or reducing VAT on sunscreen products, were excluded because they were not in the remit", url: `${nice("ph32")}/chapter/Recommendations`, date: "2016-02-09" },
  ng34: { label: "NICE NG34: sunlight exposure, risks and benefits, published 9 February 2016. Eighteen recommendations, 1.1.1 to 1.1.18, all of them about who is at risk, what message to give, mass media campaigns and a local strategic approach. Recommendation 1.1.1 names outdoor workers and people with outdoor hobbies among the at-risk groups; the guideline contains no recommendation on regulation, taxation, provision of sunscreen or protective clothing", url: `${nice("ng34")}/chapter/Recommendations`, date: "2016-02-09" },
  crukNmsc: { label: "Cancer Research UK: non-melanoma skin cancer statistics. Around 156,000 new cases a year in the UK, nearly 430 a day (2019, 2021 to 2022); 1,200 deaths a year (2022 to 2024); 48 percent of new cases in people aged 75 and over", url: `${CRUK}/non-melanoma-skin-cancer`, date: "2026-09-25" },
  crukNmscIncidence: { label: "Cancer Research UK: non-melanoma skin cancer incidence statistics. Around 67,500 new cases a year in females and 88,500 in males (2016 to 2018); rates have risen by 169 percent since the early 1990s and by 42 percent in the last decade; in England the European age-standardised rate is 40 percent lower in females and 42 percent lower in males in the most deprived fifth than in the least deprived (2013 to 2017), so around 25,000 fewer cases a year occur than if every deprivation quintile had the incidence of the least deprived", url: `${CRUK}/non-melanoma-skin-cancer/incidence`, date: "2026-09-25" },
  crukNmscRisk: { label: "Cancer Research UK: non-melanoma skin cancer risk factors. An estimated 50 to 70 percent of squamous cell carcinoma and 50 to 90 percent of basal cell carcinoma in fair-skinned people are caused by ultraviolet radiation; basal cell carcinoma risk is 43 percent higher in people who work outdoors and squamous cell carcinoma risk 77 percent higher in outdoor workers than indoor workers, on meta-analyses; squamous cell carcinoma risk is at least 67 percent higher and basal cell carcinoma risk up to 29 percent higher in people who have ever used a sunbed, and basal cell carcinoma risk 40 percent higher in people who first used one before 25; an estimated 7 percent of non-melanoma skin cancers in men and 1 percent in women in Britain are due to occupational exposures including solar radiation", url: `${CRUK}/non-melanoma-skin-cancer/risk-factors`, date: "2026-09-25" },
  crukMelanomaIncidence: { label: "Cancer Research UK: melanoma skin cancer incidence statistics. Melanoma is the 5th most common cancer in the UK with around 19,400 new cases a year, 53 a day (2019, 2021 to 2022); rates have risen by 164 percent since the early 1990s and by 26 percent in the last decade, and are projected to reach around 26,500 cases a year by 2038 to 2040", url: `${CRUK}/melanoma-skin-cancer/incidence`, date: "2026-09-25" },
  crukMelanomaRisk: { label: "Cancer Research UK: melanoma skin cancer risk factors. 86 percent of melanoma cases in the UK are preventable and 86 percent are caused by overexposure to ultraviolet radiation; an estimated 100 melanoma deaths a year in the UK are caused by sunbed use; melanoma risk is 16 to 25 percent higher in people who have ever used a sunbed and 59 percent higher in people who first used one before 35; 5 to 6 percent of young people use or have used sunbeds on 2008 and 2009 data, and 2 percent of British adults trying to get a tan do so with a sunbed only on 1999 data", url: `${CRUK}/melanoma-skin-cancer/risk-factors`, date: "2026-09-25" },
  crukSunUv: { label: "Cancer Research UK: sun, UV and cancer, the public-facing prevention information behind the SunSmart messages", url: "https://www.cancerresearchuk.org/about-cancer/causes-of-cancer/sun-uv-and-cancer", date: "2026-09-25" },
  sunbedsAct: { label: "Sunbeds (Regulation) Act 2010 (2010 chapter 20), which extends to England and Wales only. Section 2 makes it an offence for a sunbed business to let anyone under 18 use a sunbed on relevant premises, to offer one to a person under 18, or to allow a person under 18 into a restricted zone. Sections 4, 5 and 6 are powers, not duties: regulations may require supervision, may prohibit or restrict the sale or hire of sunbeds to under-18s, may require health information to be provided and displayed and may require protective eyewear. Section 7 puts enforcement on local authorities", url: "https://www.legislation.gov.uk/ukpga/2010/20/data.htm", date: "2026-09-25" },
  sunbedsWales: { label: "The Sunbeds (Regulation) Act 2010 (Wales) Regulations 2011, 2011 No. 1130 (W. 156). Wales used the powers in sections 4 to 6 of the Act: regulation 3 prevents sunbed use by children on domestic premises, 4 requires supervision of sunbed use, 5 prohibits the sale or hire of sunbeds to under-18s, 6 covers remote sale or hire, 7 requires prescribed health information to be provided and displayed, and 8 requires protective eyewear", url: "https://www.legislation.gov.uk/wsi/2011/1130/contents/made", date: "2026-09-25" },
  sunbedsScotland: { label: "Public Health etc. (Scotland) Act 2008, Part 8, regulation of provision of sunbeds, in force from 1 December 2009. Section 95 makes it an offence to allow a person under 18 to use a sunbed on sunbed premises, 96 to sell or hire a sunbed to a person under 18, 97 covers remote sale or hire, 98 makes it an offence to allow unsupervised use of a sunbed, 100 imposes a duty to provide prescribed health information every time a person proposes to use a sunbed, and 101 a duty to display an information notice", url: "https://www.legislation.gov.uk/asp/2008/5/part/8", date: "2026-09-25" },
  sunbedsNi: { label: "Sunbeds Act (Northern Ireland) 2011 (2011 chapter 19). It is the widest of the four: as well as the under-18 prohibitions in sections 1 and 2 it prohibits unsupervised use (section 3), imposes duties to provide and display information (4 and 5), prohibits the display of other health claims (6), requires protective eyewear (7), sets requirements for staff training (8) and for the sunbeds themselves (9), and provides for fixed penalties (12) and for the registration or licensing of sunbed premises or operators (14)", url: "https://www.legislation.gov.uk/nia/2011/19/contents", date: "2026-09-25" },
  legSearch: { label: "legislation.gov.uk title search for \"sunbeds\", which returns ten results: the 2010 Act, the Northern Ireland Act of 2011 and its three statutory rules, the Welsh regulations of 2011, and two Scottish statutory instruments. No statutory instrument has ever been made under sections 4, 5 or 6 of the 2010 Act for England", url: "https://www.legislation.gov.uk/all?title=sunbeds", date: "2026-09-25" },
  hseSun: { label: "Health and Safety Executive: skin at work, outdoor workers and sun exposure. The guidance names farm and construction workers, market gardeners, outdoor activity workers and some public service workers as at risk, and advises keeping a top on, a hat with a brim or flap, shade during breaks, sunscreen of at least SPF30 on exposed skin, water, and regular self-examination. It is advice: the page imposes no duty to provide sunscreen or shade", url: "https://www.hse.gov.uk/skin/sunprotect.htm", date: "2026-09-25" },
  iiac: { label: "Industrial Injuries Advisory Council and Department for Work and Pensions: non-melanoma skin cancer and occupational exposure to (natural) UV radiation, information note published 25 April 2018. After reviewing the evidence the Council decided not to make any recommendation for changes to the list of prescribed diseases for which people can claim Industrial Injuries Disablement Benefit", url: "https://www.gov.uk/government/publications/non-melanoma-skin-cancer-and-occupational-exposure-to-natural-uv-radiation-iiac-information-note", date: "2018-04-25" },
  vatRates: { label: "GOV.UK: VAT rates. The standard rate is 20 percent and applies to most goods and services", url: "https://www.gov.uk/vat-rates", date: "2026-09-25" },
  skcinVat: { label: "Skcin, the Karen Clifford Skin Cancer Charity: the VAT Burn campaign, which asks the government to reclassify SPF30 and above sunscreen as an essential healthcare item rather than a luxury subject to VAT. The page cites research conducted for Tesco with Skcin in 2021 in which 57 percent of the UK population considered sunscreen expensive, 31 percent of parents said they could not always afford it for the whole family and 44 percent said they put it on their children but not on themselves or their partner because of cost, and quotes the government's reply that VAT brings in vital public funds, that changing it for an individual product involves a trade-off, and that sunscreen is available to some on prescription", url: "https://www.skcin.org/resources/vat-burn-campaign/", date: "2026-09-25" },
  nhsSun: { label: "NHS: sunscreen and sun safety. The NHS advice is shade between 11am and 3pm from March to October in the UK, clothing, a wide-brimmed hat, sunglasses, and at least SPF30 with a 4-star UVA rating applied generously and reapplied", url: "https://www.nhs.uk/live-well/seasonal-health/sunscreen-and-sun-safety/", date: "2026-09-25" },

  // ---------- Nations ----------
  phsCwt: { label: "Public Health Scotland: cancer waiting times, 1 January to 31 March 2026, published 30 June 2026", url: "https://publichealthscotland.scot/publications/cancer-waiting-times/cancer-waiting-times-1-january-to-31-march-2026/", date: "2026-06-30" },
  phsCwtTable: { label: "Public Health Scotland: cancer waiting times table 1, compliance with standard, quarter ending 31 March 2026. The inclusion criteria list the cancer types for which Scotland records data, and the skin entry reads \"melanoma, new primary invasive (i.e. Clark level greater than 1, melanoma of any site except eye); includes C43 (Skin)\": C44 is not on the list at all, so no keratinocyte cancer, including cutaneous squamous cell carcinoma, is covered by a Scottish waiting-time standard. In the quarter, 163 of 188 eligible melanoma referrals started treatment within 62 days (86.7 percent), with a median wait of 25 days and a 95th percentile of 110 days, against 3,372 of 4,668 (72.2 percent) for all cancer types", url: "https://publichealthscotland.scot/media/39235/2026-06-30-cwt-table-1-compliance-to-standard.xlsx", date: "2026-06-30" },
  walesPerf: { label: "Welsh Government: NHS activity and performance summary, July and August 2026. In July 2026, 60.1 percent of suspected cancer pathways started first definitive treatment within 62 days of a suspicion of cancer, against a 75 percent target, on 2,248 treatments; 18,429 new suspected cancer pathways were opened and 15,052 were closed after the patient was told they did not have cancer; Cwm Taf Morgannwg was highest at 67.5 percent and Swansea Bay lowest at 44.7 percent. The summary is all-cancer and publishes no tumour-site split", url: "https://www.gov.wales/nhs-activity-and-performance-summary-july-and-august-2026-html", date: "2026-09" },
  niCwt: { label: "Department of Health (Northern Ireland): cancer waiting times, January to March 2026. The publication notes that 62-day data are undergoing further validation and are not included for the quarter ending 31 March 2026", url: "https://www.health-ni.gov.uk/publications/northern-ireland-waiting-time-statistics-cancer-waiting-times-january-march-2026", date: "2026-07" },
  niCwtTable: { label: "Department of Health (Northern Ireland): cancer waiting times workbook, quarter ending March 2026, 31-day wait by tumour site. Skin cancers: 166 of 190 within 31 days in January 2026, 117 of 134 in February and 116 of 122 in March, 399 of 446 across the quarter (89.5 percent), with a median wait of 0 days and a 95th percentile of 31 days in March. The workbook answers HTTP 403 to a browser user agent and 200 to a plain request with no extra headers, which is how it was read", url: "https://www.health-ni.gov.uk/sites/default/files/2026-07/hs-niwts-cwt-q4-25-26.xlsx", date: "2026-07" },
  niCwtIcd: { label: "Department of Health (Northern Ireland): cancer waiting times ICD-10 mapping, quarter ending March 2026. C43 malignant melanoma of skin and C44 \"other malignant neoplasms of skin (except basal cell carcinoma)\" both map to the Skin Cancers tumour site, so Northern Ireland counts cutaneous squamous cell carcinoma and excludes basal cell carcinoma, as England does. The workbook answers HTTP 403 to a browser user agent and 200 to a plain request", url: "https://www.health-ni.gov.uk/sites/default/files/2026-07/hs-niwts-cwt-icd10-q4-25-26.xlsx", date: "2026-07" },
  ni62: { label: "Department of Health (Northern Ireland): cancer waiting times, revised 62-day waits for quarters ending December 2023 to March 2026, published September 2026. The target is that at least 95 percent of patients begin first definitive treatment within 62 days of an urgent GP referral for suspected cancer; in the quarter ending 31 March 2026, 29.6 percent did. There is no tumour-site split. The file answers HTTP 403 to a browser user agent and 200 to a plain request", url: "https://www.health-ni.gov.uk/sites/default/files/2026-09/ni-cancer-waiting-times-2026-revised.pdf", date: "2026-09" },

  // ---------- Centres ----------
  gsttSkin: { label: "Guy's and St Thomas' NHS Foundation Trust: skin cancer. The trust treats basal cell carcinoma, squamous cell carcinoma, melanoma, skin lymphoma, Merkel cell carcinoma and Kaposi's sarcoma; the service is part of St John's Institute of Dermatology; non-melanoma surgery is done in the dermatology clinics or the dermatological surgery and laser unit and most melanoma surgery by the plastic surgery team. Page last updated April 2025. The page answers HTTP 403 to a browser user agent and 200 to a plain request with no extra headers, which is how it was read", url: "https://www.guysandstthomas.nhs.uk/our-services/skin-cancer", date: "2025-04" },
  cuhDerm: { label: "Cambridge University Hospitals: dermatology. All consultants run general dermatology clinics, see skin cancer patients and carry out minor procedures in the department", url: "https://www.cuh.nhs.uk/our-services/dermatology/", date: "2026-09-25" },
  newcastleDerm: { label: "Newcastle Hospitals NHS Foundation Trust: dermatology. Some of the trust's specialists perform micrographic surgery, a type of surgery for removing certain forms of skin cancer", url: "https://www.newcastle-hospitals.nhs.uk/services/dermatology/", date: "2026-09-25" },
  nnuhDerm: { label: "Norfolk and Norwich University Hospitals NHS Foundation Trust: dermatology, the department led by the Getting It Right First Time national dermatology clinical lead", url: "https://www.nnuh.nhs.uk/departments/dermatology/", date: "2026-09-25" },
  ncaDerm: { label: "Northern Care Alliance NHS Foundation Trust: the Dermatology Centre at Salford Royal, described by the trust as one of the largest of its kind in Europe, seeing around 13,000 new outpatients a year with a further 26,000 follow-up appointments, with academic links to the University of Manchester and The Christie", url: "https://www.northerncarealliance.nhs.uk/our-services/dermatology", date: "2026-09-25" },
  leedsDerm: { label: "Leeds Teaching Hospitals NHS Trust: dermatology. The department runs specialist clinics for skin cancer, Mohs micrographic surgery, pigmented lesions, melanoma, dermatology lymphoma, photodynamic therapy and a minor surgery clinic", url: "https://www.leedsth.nhs.uk/services/dermatology/", date: "2026-09-25" },
  uhbDerm: { label: "University Hospitals Birmingham NHS Foundation Trust: dermatology", url: "https://www.uhb.nhs.uk/services/dermatology/", date: "2026-09-25" },
  lothianDerm: { label: "NHS Lothian: dermatology, with its own patient sections on skin cancer, sun awareness and skin surgery and on melanoma", url: "https://services.nhslothian.scot/dermatology/", date: "2026-09-25" },
  cavDerm: { label: "Cardiff and Vale University Health Board: dermatology, the Welsh Institute of Dermatology, with a skin cancer service", url: "https://cavuhb.nhs.wales/our-services/dermatology/", date: "2026-09-25" },
  belfastDerm: { label: "Belfast Health and Social Care Trust: dermatology, with a skin cancer service", url: "https://belfasttrust.hscni.net/service/dermatology/", date: "2026-09-25" },

  // ---------- Trials ----------
  impact: { label: "ISRCTN10511385: IMPACT, efficacy and safety of first-line cemiplimab in advanced basal cell carcinoma, a phase 2 trial of three-weekly cemiplimab in people with locally advanced basal cell carcinoma, sponsored by University Hospitals Bristol and Weston NHS Foundation Trust, target 41 participants, end date 30 April 2029", url: isrctn("10511385"), date: "2026-09-25" },
  spotIt: { label: "ISRCTN80116429: SPOT-IT, cutaneous squamous cell carcinoma prevention using topical therapy in immunosuppressed patients, sponsored by Cardiff University, target 673 participants, end date 31 December 2031", url: isrctn("80116429"), date: "2026-09-25" },
  sccAfter: { label: "ISRCTN54806122: SCC-AFTER, adjuvant radiotherapy in people with high-risk primary cutaneous squamous cell carcinoma after surgery, an open-label multicentre two-arm phase 3 randomised trial sponsored by Cardiff University, target 840 participants, end date 1 January 2031", url: isrctn("54806122"), date: "2026-09-25" },
  excise: { label: "ISRCTN15382058: EXCISE, examining antibiotics for ulcerated skin cancer surgical excision, a pragmatic double-blinded clinical and cost-effectiveness randomised controlled trial sponsored by Cardiff and Vale University Health Board, target 380 participants, end date 31 December 2027", url: isrctn("15382058"), date: "2026-09-25" },
  octopus: { label: "ISRCTN15698540: OCTOPUS, optical coherence tomography in outpatient dermatology units, a non-randomised pilot cohort study of optical coherence tomography and line-field confocal optical coherence tomography imaging for diagnosing skin cancers, sponsored by Barts Health NHS Trust, target 200 participants, end date 18 May 2028", url: isrctn("15698540"), date: "2026-09-25" },
  sinsReg: { label: "ISRCTN48755084: SINS, a randomised controlled trial of excisional surgery versus imiquimod 5% cream for nodular and superficial basal cell carcinoma, sponsored by the University of Nottingham, target 501 participants, recruitment 19 June 2003 to 22 February 2007", url: isrctn("48755084"), date: "2026-09-25" },
  sinsPaper: { label: "Bath-Hextall F, Ozolins M, Armstrong SJ, Colver GB, Perkins W, Miller PS, Williams HC. Surgical excision versus imiquimod 5% cream for nodular and superficial basal-cell carcinoma (SINS): a multicentre, non-inferiority, randomised controlled trial. Lancet Oncology 2014", url: "https://doi.org/10.1016/S1470-2045(13)70530-8", date: "2014" },
  sins5y: { label: "Williams HC, Bath-Hextall F, Ozolins M, Armstrong SJ, Colver GB, Perkins W, Miller PSJ. Surgery versus 5% imiquimod for nodular and superficial basal cell carcinoma: 5-year results of the SINS randomized controlled trial. Journal of Investigative Dermatology 2017. Five-year success 82.5 percent (170 of 206) for imiquimod against 97.7 percent (173 of 177) for surgery, relative risk 0.84 (95 percent confidence interval 0.77 to 0.91); most imiquimod failures occurred in the first year", url: "https://doi.org/10.1016/j.jid.2016.10.019", date: "2017" },
  molemateReg: { label: "ISRCTN79932379: the MoleMate UK Trial, the management of suspicious pigmented lesions in primary care, sponsored by the University of Cambridge and Cambridgeshire NHS Primary Care Trust, target 1,800 and final enrolment 1,297", url: isrctn("79932379"), date: "2026-09-25" },
  molematePaper: { label: "Walter FM, Morris HC, Humphrys E, Hall PN, Prevost AT, Burrows N, Bradshaw L, Wilson EC, Norris P, Walls J, Johnson M, Kinmonth AL, Emery JD. Effect of adding a diagnostic aid to best practice to manage suspicious pigmented lesions in primary care: randomised controlled trial. BMJ 2012 (the DOI resolves to bmj.com, which answers HTTP 403 to a program; the abstract and figures above were read from the Europe PMC record, PubMed id 22763392)", url: "https://doi.org/10.1136/bmj.e4110", date: "2012" },
  mccReg: { label: "ISRCTN16290169: rational treatment selection for Merkel cell carcinoma, a randomised phase 3 multicentre trial comparing radical surgery and radical radiotherapy as first definitive treatment for primary Merkel cell carcinoma, with an observational study for people ineligible for the randomised comparison, sponsored by the University of Birmingham, target 400, recruitment 31 March 2016 to 30 December 2018, overall end date 30 September 2020. The registry record lists no publication", url: isrctn("16290169"), date: "2026-09-25" },

  // ---------- People, charities and benefits ----------
  hywelWilliams: { label: "University of Nottingham: Hywel Williams, Professor of Dermato-Epidemiology and Co-Director of the Centre of Evidence Based Dermatology", url: "https://www.nottingham.ac.uk/medicine/people/hywel.williams", date: "2026-09-25" },
  cebd: { label: "University of Nottingham: the Centre of Evidence Based Dermatology", url: "https://www.nottingham.ac.uk/research/groups/cebd/index.aspx", date: "2026-09-25" },
  melanomaFocus: { label: "Melanoma Focus: the Melanoma Helpline, a confidential freephone service on 0808 801 0777 staffed by specialist skin cancer nurses, open 1pm to 2pm and 7pm to 9pm Monday to Friday and 7pm to 9pm on Sunday, with a message service outside those hours. The page states plainly that the nurses cannot diagnose melanoma on the telephone or from a photograph", url: "https://melanomafocus.org/melanoma-helpline/", date: "2026-09-25" },
  melanomaFocusHome: { label: "Melanoma Focus: information, guidance and support for patients, carers and healthcare professionals, and a community of melanoma specialists", url: "https://melanomafocus.org/", date: "2026-09-25" },
  badPatient: { label: "British Association of Dermatologists: Skin Health Info, the association's patient information service, with a leaflet for basal cell carcinoma", url: "https://www.skinhealthinfo.org.uk/condition/basal-cell-carcinoma/", date: "2026-09-25" },
  skcin: { label: "Skcin, the Karen Clifford Skin Cancer Charity, founded in 2006, which runs national skin cancer prevention and early detection campaigns and accreditation schemes", url: "https://www.skcin.org/", date: "2026-09-25" },
  changingFaces: { label: "Changing Faces: the UK charity for people with a visible difference, with a Skin Camouflage Service and a support and information line on 0300 012 0275", url: "https://www.changingfaces.org.uk/", date: "2026-09-25" },
  macmillanSkin: { label: "Macmillan Cancer Support: skin cancer information and support", url: "https://www.macmillan.org.uk/cancer-information-and-support/skin-cancer", date: "2026-09-25" },
  nhsNmsc: { label: "NHS: non-melanoma skin cancer, with sections on what it is, symptoms, causes, tests and next steps, and treatment. Page last reviewed 16 September 2026", url: "https://www.nhs.uk/conditions/non-melanoma-skin-cancer/", date: "2026-09-16" },
  nhsNmscTreatment: { label: "NHS: treatment for non-melanoma skin cancer. Surgery is the main treatment; radiotherapy, targeted medicines and immunotherapy, photodynamic therapy and chemotherapy cream are also used", url: "https://www.nhs.uk/conditions/non-melanoma-skin-cancer/treatment/", date: "2026-09-16" },
  nhsMelanoma: { label: "NHS: melanoma skin cancer", url: "https://www.nhs.uk/conditions/melanoma-skin-cancer/", date: "2026-09-25" },
  medex: { label: "NHS Business Services Authority: medical exemption certificates, valid five years for cancer, the effects of cancer or its treatment", url: "https://www.nhsbsa.nhs.uk/help-nhs-prescription-costs/medical-exemption-certificates", date: "2026-09-25" },
} satisfies Record<string, UkSource>;

// ======================= INSTITUTIONS =======================
type I = Omit<InstitutionInput, "kind" | "asOf">;
const inst = (x: I): InstitutionInput => ({ kind: "institution", asOf, ...x });

const institutions: InstitutionInput[] = [
  inst({ id: "melanoma-focus", name: "Melanoma Focus", city: "Cambridge", country: "GB", lat: 52.205, lng: 0.119, institutionType: "consortium", website: S.melanomaFocusHome.url,
    tldr: "The UK melanoma charity whose free nurse helpline is the one place a frightened person can ask a specialist skin cancer nurse a question without waiting for an appointment, and which says up front that it cannot tell you from a photograph.",
    summary: "Melanoma Focus runs the Melanoma Helpline, a confidential freephone service on 0808 801 0777 staffed by specialist skin cancer nurses. It is open 1pm to 2pm and 7pm to 9pm Monday to Friday and 7pm to 9pm on Sunday, with a message service outside those hours and an email contact form. The charity states plainly on the helpline page that its nurses cannot diagnose melanoma on the telephone or from a photograph, and points people who have been asked by a GP to send an image to its own teledermatology guidance on how to take one.\n\nIt also runs support groups and produces guidelines and information for healthcare professionals as well as patients. Its remit is melanoma rather than the keratinocyte cancers, which is worth knowing: a person with a basal cell carcinoma who telephones will be helped, but the charity built for them is the British Association of Dermatologists' patient information service, and the charity built for the consequences of facial skin surgery is Changing Faces.",
    links: [{ label: "Melanoma Helpline", url: S.melanomaFocus.url }],
    cancers: ["melanoma", "skin-cancer"], tags: ["uk", "charity", "skin", "support"] }),
  inst({ id: "skcin", name: "Skcin (the Karen Clifford Skin Cancer Charity)", city: "Nottingham", country: "GB", lat: 52.954, lng: -1.149, institutionType: "consortium", website: S.skcin.url,
    tldr: "The prevention charity that campaigns on the one lever in skin cancer that is bigger than any drug: what the country does about ultraviolet exposure, and what it charges for sunscreen.",
    summary: "Skcin was founded in 2006 and works on skin cancer prevention and early detection across both melanoma and the keratinocyte cancers, running accreditation schemes for schools, nurseries, workplaces and outdoor venues.\n\nIts most visible policy work is the VAT Burn campaign, which asks the government to reclassify SPF30 and above sunscreen as an essential healthcare item rather than a cosmetic subject to the standard 20 percent rate of VAT. The campaign page cites research conducted for Tesco with Skcin in 2021 in which 57 percent of the UK population considered sunscreen expensive, 31 percent of parents said they could not always afford it for the whole family and 44 percent said they put it on their children but not on themselves or their partner because of the cost. It also publishes the government's reply: that VAT brings in vital public funds, that changing it for an individual product involves a trade-off, and that sunscreen is available to some on prescription. The exchange is worth reading beside NICE PH32, which excluded fiscal and legislative actions, including reducing VAT on sunscreen, from its remit entirely.",
    links: [{ label: "VAT Burn campaign", url: S.skcinVat.url }],
    cancers: ["skin-cancer", "melanoma", "basal-cell-carcinoma", "cutaneous-scc"], tags: ["uk", "charity", "prevention", "skin"] }),
  inst({ id: "british-association-of-dermatologists", name: "British Association of Dermatologists", city: "London", country: "GB", lat: 51.523, lng: -0.139, institutionType: "consortium", website: S.badPatient.url,
    tldr: "The professional body that writes the UK's skin cancer service standards and, because these cancers have almost no charity of their own, also writes most of the patient information a person with a basal cell carcinoma will be handed.",
    summary: "The British Association of Dermatologists sets the service standards British skin cancer surgery is judged against. Its 2020 service guidance and standards for Mohs micrographic surgery were developed within a NICE-accredited framework and co-badged by the Royal College of Pathologists, the British Association of Oral and Maxillofacial Surgeons, ENT UK, the British Society for Dermatological Surgery, the British Society for Dermatopathology and the British Oculoplastic Surgery Society; the Getting It Right First Time dermatology report treats them as the answer to unwarranted variation in how Mohs is done.\n\nIt was one of the bodies that developed NHS England's teledermatology roadmap and the multidisciplinary consensus group behind the timed skin cancer diagnostic pathway. Its patient information service publishes leaflets on basal cell carcinoma, squamous cell carcinoma and melanoma, which matters because the keratinocyte cancers have no large patient charity of their own in the way breast, prostate and bowel cancer do.",
    links: [{ label: "Skin Health Info: basal cell carcinoma", url: S.badPatient.url }],
    cancers: ["skin-cancer", "basal-cell-carcinoma", "cutaneous-scc"], tags: ["uk", "professional-body", "skin", "standards"] }),
];

